using System;using System.IO;using System.Linq;using System.Drawing;using System.Diagnostics;
internal static partial class NativeBackground{
 static readonly int[] PaletteIndexes={1,2,3,4,18,6,248,249};
 const long AppearanceFlag=0xbbd93c4,PaletteDual=0xb897a60,PaletteColors=0xbba9d30;
 static int palettePid;static long paletteStart;static bool paletteOwned;
 public static int? ActualAppearance(){ValidateFile();var p=Process.GetProcessesByName("Weixin").FirstOrDefault(x=>x.MainWindowHandle!=IntPtr.Zero);if(p==null)return null;long image=0;foreach(ProcessModule m in p.Modules)if(m.ModuleName=="Weixin.dll")image=m.BaseAddress.ToInt64();if(image==0)return null;var h=OpenProcess(0x410,false,p.Id);if(h==IntPtr.Zero)return null;try{var flags=Read(h,image+AppearanceFlag,3);return flags[0]==1&&flags[1]==1&&flags[2]<=1?(int?)flags[2]:null;}finally{CloseHandle(h);}}
 internal static Theme OriginalPalette(){var colors=new string[16];for(int i=0;i<16;i++)colors[i]=Palette.Decode(Palette.Hex(Palette.Originals[i]),0);return new Theme{Name="微信原始配色",Colors=colors};}
 internal static byte[] ColorBytes(Color c){var b=new byte[16];BitConverter.GetBytes(1).CopyTo(b,0);BitConverter.GetBytes((ushort)65535).CopyTo(b,4);BitConverter.GetBytes((ushort)(c.R*257)).CopyTo(b,6);BitConverter.GetBytes((ushort)(c.G*257)).CopyTo(b,8);BitConverter.GetBytes((ushort)(c.B*257)).CopyTo(b,10);return b;}
 static bool MainRootVisible(IntPtr h,long image){try{long root=cachedChatRoot;if(root==0&&cachedInstance!=0){root=cachedInstance;for(int i=0;i<32;i++){long next=Pointer(h,Pointer(h,root+8)+16);if(next==0)break;root=next;}}return root!=0&&WidgetClass(h,image,root)=="mmui::MainWindow"&&(BitConverter.ToUInt32(Read(h,Pointer(h,root+0x28)+8,4),0)&32768)!=0;}catch{return false;}}
 // The writable color caches are version-scoped. No code, string keys or QColor tail fields are written.
 internal static bool SyncNativePalette(bool allowTheme){if(InternalModulePresent())return false;ValidateFile();var p=Process.GetProcessesByName("Weixin").FirstOrDefault(x=>x.MainWindowHandle!=IntPtr.Zero);if(p==null)return false;long image=0;foreach(ProcessModule m in p.Modules)if(m.ModuleName=="Weixin.dll")image=m.BaseAddress.ToInt64();if(image==0)return false;var h=OpenProcess(0x438,false,p.Id);if(h==IntPtr.Zero)return false;try{var flags=Read(h,image+AppearanceFlag,3);if(flags[0]!=1||flags[1]!=1||flags[2]>1)return false;int mode=flags[2];AppearanceProfiles.Observe(mode);bool main=allowTheme&&MainRootVisible(h,image);bool same=palettePid==p.Id&&paletteStart==p.StartTime.ToUniversalTime().Ticks;if(!same){paletteOwned=false;palettePid=p.Id;paletteStart=p.StartTime.ToUniversalTime().Ticks;}if(!main&&!paletteOwned)return false;Theme theme=main?Engine.ActiveTheme:OriginalPalette();if(theme==null)return false;
  foreach(int index in PaletteIndexes){var value=Read(h,image+PaletteColors+index*24,16);if(BitConverter.ToUInt32(value,0)!=1||BitConverter.ToUInt16(value,4)!=65535)throw new IOException("微信颜色缓存布局校验失败，未应用主题。");}
  for(int key=0;key<8;key++){int index=PaletteIndexes[key];var dual=new byte[8];for(int m=0;m<2;m++){Color c=ColorTranslator.FromHtml(theme.Colors[key*2+m]);dual[m*4]=c.R;dual[m*4+1]=c.G;dual[m*4+2]=c.B;dual[m*4+3]=255;}long pair=image+PaletteDual+index*8;if(!Read(h,pair,8).SequenceEqual(dual))Write(h,pair,dual);byte[] active=ColorBytes(ColorTranslator.FromHtml(theme.Colors[key*2+mode]));long at=image+PaletteColors+index*24;if(!Read(h,at,16).SequenceEqual(active))Write(h,at,active);}
  paletteOwned=main;return main;
 }finally{CloseHandle(h);}}
}
